CH = dict(num=5, tag="History", theme="Early humans, Stone Age to Bronze Age, Harappan origins and river-valley civilisations",
 title="Early Humans and the Beginning of Civilisation",
 intro="Human history stretches back millions of years, long before kingdoms or writing. This chapter traces our ancestors from Africa through the Palaeolithic, Mesolithic and Neolithic ages, the early Harappan phase, and the Bronze Age civilisations of Mesopotamia, Egypt and China.",
 big_questions=["How did humans live before civilisation began?", "How did humans communicate before writing was invented?", "How does archaeology help us understand the past?", "How did early civilisations interact with each other?"],
 blocks=[
 ("h2", "Writing and the Study of the Past"),
 ("p", "The time before writing is known mainly through **archaeological evidence**. Writing appeared at different times in different places. The **Harappan (Sindhu–Sarasvatī / Indus Valley) script**, found on seals and pottery, is pictographic and **still undeciphered** (also called Sindhu lipi). The **cuneiform** of the Sumerians (Mesopotamia) and the **hieroglyphs** of Egypt were contemporary with the Harappans but **have been deciphered**; they mark the start of the historical period about **5,000 years ago**. **Brahmi** was used from about 400 BCE in southern India and the Ganga valley and was formalised by Emperor **Aśhoka** (3rd century BCE)."),
 ("table", ["", "Before writing", "After writing"], [
  ["Share of human history", "More than 99% (about 3 million to 5,000 years ago)", "Less than 1% (last 5,000 years)"],
  ["Main sources", "Tools and other artefacts", "Material remains **and** written documents"],
  ["Knowledge of people", "Hard to know thoughts and ideas", "Literature gives names, events, social, political, cultural life"],
  ["Measuring time", "Only approximate dating", "Fairly accurate because documents note dates (coronations, wars)"]]),
 ("h2", "Why Study Early Human History?"),
 ("ul", ["It shows the long process of **biological evolution** (gradual physical/genetic change from **australopithecines**, 'southern apes', to modern humans, **Homo sapiens**) and **cultural evolution** (adapting to surroundings in the **Quaternary Period**, the last 26 lakh years).", "Humans developed tools and technology; ways of life shifted from hunting and gathering to **agriculture and food production**. The ability to produce **surplus** laid the foundation for civilisation."]),
 ("h3", "Our ancestors"),
 ("table", ["Ancestor", "Where / when", "Features"], [
  ["**Homo habilis** ('handy man')", "Olduvai Gorge, Tanzania and Kenya; about 2–6 million years ago (as given)", "Made chopper stone tools; early toolmaker"],
  ["**Homo erectus** (upright, bipedal)", "Eastern African Rift Valley; about 2 million years ago", "Made **handaxes and cleavers**; first hominin to leave Africa, spreading to Asia and Europe"],
  ["**Homo neanderthalensis**", "Europe and Southwest Asia, until about 40,000 years ago", "Made Middle Palaeolithic flake tools"],
  ["**Homo sapiens** (modern humans)", "Evolved in Africa about 300,000 years ago; exit about 125,000 years ago", "Only living human species; developed complex technologies; spread worldwide"]]),
 ("ul", ["**Hominins** include modern humans and our human-like ancestors. About **3.3 million years ago** one early ancestor made the first stone tools; toolmaking marks the start of 'human behaviour'. Tools are called **extra-corporal limbs** (extensions of the body).", "The earliest settlements were in Africa, Asia and Europe: the **Old World**.", "A **fossil** is the preserved remains, trace or impression of a plant, animal or human of the distant past, formed when remains are buried and slowly turn to stone. Tools and fossils are the main evidence. Archaeologists excavate sites and also **experiment** by making and using similar tools."]),
 ("h2", "Periods of Early Human History"),
 ("table", ["Period", "Way of life", "Tools / technology"], [
  ["**Palaeolithic** (Old Stone Age)", "Hunter–gatherers; caves and open camps", "Simple stone tools; handaxes, cleavers; later scrapers, borers, points; bow and arrow, blades and microblades"],
  ["**Mesolithic**", "Transition between hunting–gathering and farming; warmer climate; fishing", "Microlithic (tiny stone) tools"],
  ["**Neolithic** (New Stone Age)", "Farming, domestication, permanent villages, pottery, weaving", "Polished stone tools; tools for food production"],
  ["**Chalcolithic** (Copper–Stone)", "Early farming communities", "Copper with stone; early metallurgy (extraction and shaping of metals)"],
  ["**Bronze Age**", "Trade, towns, early civilisations", "Bronze (copper + tin)"],
  ["**Iron Age**", "More advanced societies", "Widespread iron smelting; stronger tools and weapons"]]),
 ("h3", "Palaeolithic hunter–gatherers in India"),
 ("ul", ["India's oldest settlements date to about **2 million years ago**. **Attirampakkam** (Tamil Nadu): about 1.5–1.7 million years. **Isampur** (Karnataka): 1.2 million years. Animal fossils, handaxes and cleavers have been found; these were used to chop meat, dig tubers, scrape skins and break bones for marrow.", "Later: smaller tools (**scrapers, borers, points**) improved hunting by tipping projectiles; then the **bow and arrow**, parallel-sided **blades and microblades** (very sharp glassy rock), small-game hunting, **cave paintings**, body pigments and the first beads of stone, bone and shell. A **burin** (engraver) carved symbols on bone and shell. Microblades were fixed in handles.", "Homo sapiens spread over the world, including Australia and the Americas, between **50,000 and 12,000 years ago**."]),
 ("h3", "Mesolithic hunter–gatherers"),
 ("p", "About **12,000 years ago** the climate warmed. Forests and grasslands spread over former ice sheets, giving small game, fish and wild grains, so the world saw its first **population explosion**. Microlithic tools helped gather marine and freshwater food; **fishing** was the mainstay. Art flourished and caves and rock shelters were used often. **Bhimbetka** (Madhya Pradesh), a World Heritage Site, has rich cave art."),
 ("h3", "The Neolithic Revolution"),
 ("ul", ["Hunter–gatherers gained knowledge of seasons and food resources and slowly turned to **food production**: **domestication** of select animals and plants, with new breeds through cultivation and animal husbandry. This is the **Neolithic revolution**.", "Farmers made tools for producing and processing food, made **pottery**, used many raw materials and set up the first **village settlements**, laying the base for the **urban revolution**.", "The shift happened at different times in different regions (West Asia: wheat, barley; India: millets; Ganga plains and Yangtze: rice; North China: millets; West Africa: pearl millet)."]),
 ("h3", "Neolithic in the Indian subcontinent"),
 ("ul", ["**Mehrgarh** (Bolan River, present-day Pakistan; foothills of Baluchistan) is the oldest Neolithic site and earliest agricultural village, about **7000 BCE**. People built sun-dried mud-brick houses and granaries, buried the dead in graves, made ornaments from lapis lazuli, carnelian and shell, grew **wheat and barley**, and raised sheep, goats and the zebu humped cattle.", "They were the first to make **copper** objects and became **Chalcolithic** by about **4000 BCE**, laying the basis for the Bronze Age Sindhu–Sarasvatī civilisation around 3500 BCE (as given).", "By **2500 BCE** most of the subcontinent had Neolithic farming communities with herding of cattle, sheep and goats and cultivation of cereals, millets and pulses. A Neolithic site on a granite hill: **Sanganakallu** (about 2000 BCE)."]),
 ("h2", "Origins of the Sindhu–Sarasvatī Civilisation"),
 ("table", ["Phase", "Approximate date"], [["Neolithic", "From 7000 BCE"], ["Chalcolithic", "From about 4500/4000 BCE"], ["Bronze Age / Early Harappan", "About 3300–2600 BCE"], ["Mature Harappan", "2600–1900 BCE"], ["Late Harappan", "1900–1300 BCE"]]),
 ("ul", ["Copper tools in the fertile plains of the Indus and Ghaggar-Sarasvatī basins raised productivity. Radiocarbon dates suggest a pre-Harappan phase at **Bhirrana** and **Kunal** between 7000 and 5500 BCE.", "The **Early Harappan** stage shows continuity in pottery, semi-precious stone beads, shell bangles, terracotta and copper working. Beginnings of **perimeter walls, seals and script** (graffiti on pottery, simple geometric/animal seals at Harappa, Rehman Dheri, Kunal) appear.", "Bead production: Harappa, Kunal (Haryana), Datrana (Gujarat). Pottery was a major craft.", "**Kalibangan** ploughed field (about 5,000 years old) with horizontal and vertical furrows shows **double cropping**, like today's Rabi and Kharif.", "Standard weights: **binary multiples** (1, 2, 4, 8, 16 and so on) for small units and multiples of ten for larger; cubical stone weights eased long-distance trade."]),
 ("h2", "Bronze Age Civilisations Outside India"),
 ("p", "Four early civilisations arose in **river plains**: Harappan (Sindhu and Sarasvatī), **Mesopotamian** (Euphrates and Tigris, West Asia), **Egyptian** (Nile) and **Chinese** (Huang He / Yellow River). Mesopotamia and the Indus region are close, so contact and trade were strong; Egypt and China show little direct contact with the Harappans."),
 ("h3", "Mesopotamian civilisation"),
 ("ul", ["**Mesopotamia** = 'land in between' (Greek); today mainly Iraq and Kuwait with parts of Turkey and south-west Iran. The **Fertile Crescent** (Zagros and Taurus foothills from the Mediterranean to the Persian Gulf) had high agricultural potential. Farming began about 12,000 years ago; copper arrived about **4500 BCE**.", "A **city-state** is a sovereign state centred on a city that rules surrounding territory. Four major civilisations from **3500 BCE**: Sumerian, Akkadian, Assyrian, Babylonian."]),
 ("table", ["Civilisation", "Date and centre", "Key points"], [
  ["**Sumerian**", "From about 3500 BCE; Ur and other cities in Sumer (south)", "First city-based civilisation; first dams, canals; mud and burnt bricks; **ziggurat** temple (stepped pyramid temple; city grew around it, served as treasury; temple controlled economy; priests part of ruling class); invented **wheeled cart and sailboat**; base-60 number system (60-minute hour, 60-second minute, 360-degree circle); **cuneiform** from about 3200 BCE"],
  ["**Akkadian**", "2334 BCE; city of Akkad", "Language Akkadian but same cuneiform; **world's first dynastic empire**; King **Sargon** records trade with **Dilmun** (Bahrain), **Magan** (Oman) and **Meluhha** (= Sindhu–Sarasvatī); Harappans traded beads, ivory, timber, gold dust, probably copper. Literature grew (Epic of Gilgamesh)"],
  ["**Assyrian**", "About 2154 BCE to early 1700 BCE; Assur (north)", "Replaced Akkadians; dominance spread west and south"],
  ["**Babylonian**", "From 1900 BCE; central Mesopotamia", "**Hammurabi** (1792 BCE) built a large empire and compiled the **Code of Hammurabi**, a model for later laws (shown receiving the law from Shamash, god of justice). Declined by about 1400 BCE due to **Hittite** attacks (Indo-Europeans in Anatolia, modern Turkey), environmental degradation, farmland pressure, internal problems"]]),
 ("note", "DEFINITION", "**Cuneiform:** one of the earliest writing systems; wedge-shaped marks pressed into soft clay tablets with a reed stylus (Latin *cuneus* = wedge). Scribes had high status. Tablets record myths, epics, hymns, law codes, education and farming/craft records. It went out of use by the end of the first millennium BCE."),
 ("note", "NOTE", "Parallel water management in the Harappan world: **gabarbands** (check dams) in Baluchistan; the water-harvesting tanks of **Dholavira** (Kachchh); the brick dockyard at **Lothal**."),
 ("h3", "Egyptian civilisation"),
 ("ul", ["Known to Greeks and Romans; **Herodotus** wrote on it in the 5th century BCE. Sources include **papyrus** records (made from the papyrus plant; e.g. Papyrus Ebers with 700+ cures and spells). Libraries stored scrolls in labelled jars; stories like early 'Sindbad' and 'Cinderella' appear.", "**Rosetta Stone**: found in 1799 by Pierre Bouchard, a French army engineer, in three scripts including Greek; **Jean-François Champollion** deciphered hieroglyphs in **1822**.", "Egyptians called their land **Kemet** ('the black'), after the dark flood-soil. The **Nile** flooded each summer, depositing rich mud. City-states emerged about **3000 BCE**. Farmers dug ditches and reservoirs; the need for collective effort led to local government and an administrative class.", "**Calendar:** 365 days (12 months of 30 days + 5), three seasons of four months: Inundation, Peret (growing), Shemu (harvest); based on the rising of Sirius.", "**Pharaohs** were rulers; tombs developed from the **mastaba** into the **pyramid** (e.g. Step Pyramid at Saqqara). Belief in **ka** (spiritual double) led to **mummification** (organs except heart removed, body dried with natron, oiled, wrapped in linen).", "Social pyramid: Pharaoh; officials, nobles, priests; free landholders, artisans, merchants; serfs and slaves.", "Leisure and festivals (statues paraded; sistrum; **Sed festival** for the king's 30th year). Women could own property and run businesses; **Cleopatra** (69–30 BCE) became queen at 18."]),
 ("table", ["Egyptian kingdoms", "Dates"], [["Old Kingdom", "2686–2181 BCE"], ["Middle Kingdom", "2030–1650 BCE"], ["New Kingdom", "1570–1069 BCE"]]),
 ("h3", "Chinese civilisation"),
 ("ul", ["Rivers: **Huang He (Yellow River)** and **Yangtze**; Neolithic cultures about 7000 BCE; copper/bronze about 2000 BCE; urban centres about **1600 BCE**.", "Dynasties: **Shang** (1600–1046 BCE), **Zhou** (1046–256 BCE), **Qin** (221–206 BCE; first imperial dynasty, unified China, name 'China' probably from Qin), **Han** (206 BCE–220 CE). Iron common by about 600 BCE.", "Zhou kings were priest-kings, believed appointed by heaven but removable; officials were examined in archery, horsemanship, calculation, writing and music. China first developed **civil services by public examination** and **paper currency**; money economy by the 5th century BCE.", "Earliest sources: **oracle bones** (animal bones and tortoise shells heated until they cracked and read for prophecy). The script is **logographic** (characters for words).", "Crafts: **jade** objects (ritual/prestige; jade imported), marble carving, bronze weapons, tools and ritual vessels; musical jade pieces. **Silk** known from 4000–3000 BCE; under the Han (2nd century BCE) it became a major trade item, giving the **Silk Route** its name.", "**Great Wall:** walls from 680 BCE by Zhou and others against nomad raids; joined later; repaired until the 17th century CE.", "By 1500 BCE society was stratified: ruling class and nobles, then farmers and labourers."]),
 ("note", "IMPORTANT", "Common features of Bronze Age civilisations: river-valley agriculture, surplus, cities and trade, social hierarchy, administration, writing, craft specialisation and monumental building. They arose independently."),
 ("h2", "Quick Revision: Likely Exam Questions"),
 ("qa", [
  ("Why is the Harappan script not deciphered while cuneiform is?", "Harappan inscriptions are short, pictographic and no bilingual key has been found; cuneiform and hieroglyphs have been deciphered."),
  ("Differentiate the periods before and after writing.", "Before: mostly tools/artefacts, approximate dating. After: written records too, more accurate dating."),
  ("What are biological and cultural evolution?", "Biological: physical change from australopithecines to Homo sapiens. Cultural: adapting through tools and technology."),
  ("Who was Homo erectus?", "Upright ancestor (about 2 million years ago) who made handaxes and cleavers and first left Africa."),
  ("How do archaeologists know about our ancestors?", "Excavation of tools, bones and fossils, plus experiments with making tools."),
  ("Compare Palaeolithic, Mesolithic and Neolithic.", "Old Stone Age hunter-gatherers with simple tools; Mesolithic microliths and fishing with a warm climate; Neolithic farming, pottery, villages."),
  ("Why is the Neolithic called a revolution?", "Domestication of plants and animals changed the way of life, enabling villages and later cities."),
  ("Describe Mehrgarh.", "Oldest Neolithic site, about 7000 BCE, Bolan River; wheat, barley, zebu, mud-brick houses; first copper by 4000 BCE."),
  ("What features of Early Harappan led to the urban civilisation?", "Copper tools, pottery, bead-making, perimeter walls, seals, proto-script and trade integration."),
  ("What was a ziggurat?", "Stepped pyramid temple at the centre of a Sumerian city; economic and treasury centre."),
  ("Write on Hammurabi and his code.", "Babylonian king (1792 BCE) who compiled laws throughout his empire; a model for later legal systems."),
  ("What do we know about Harappan–Mesopotamian trade?", "Sargon's records name Meluhha (Harappa), Dilmun, Magan; goods: beads, ivory, timber, gold dust, copper."),
  ("How did the Nile help Egypt?", "Annual floods left fertile mud (kemet); irrigation, calendar and administration grew from it."),
  ("Why did Egyptians mummify bodies?", "They believed the ka lived on only if the body was preserved."),
  ("Give contributions of the Chinese civilisation.", "Oracle bones, jade, silk, Great Wall, civil service examinations and paper currency."),
 ]),
 ],
 takeaways=["Early human history is known mostly through archaeology: tools, fossils and cave art.", "Humans evolved in Africa (Homo habilis, Homo erectus, Homo sapiens) and spread across the world.", "Palaeolithic hunter-gatherers → Mesolithic microliths and fishing → Neolithic farming (Mehrgarh, about 7000 BCE) → Chalcolithic copper → Bronze and Iron Ages.", "The Sindhu–Sarasvatī civilisation grew out of Early Harappan farming, crafts and trade.", "Mesopotamia (Sumer, Akkad, Assyria, Babylon), Egypt and China arose in river valleys, with writing, administration and trade.", "Cuneiform and hieroglyphs are deciphered; the Harappan script is not."])
